/bin/bash -lc "node <<'NODE'
const base = 'http://localhost:8080';
let token = null;
let tokenRefreshes = 0;
let rateLimitRetries = 0;
let transientRetries = 0;

function sleep(ms) { return new Promise(resolve => setTimeout(resolve, ms)); }

function retryDelay(response, attempt) {
  const raw = response.headers.get('retry-after');
  if (raw) {
    const seconds = Number(raw);
    if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);
    const when = Date.parse(raw);
    if (Number.isFinite(when)) return Math.max(0, when - Date.now());
  }
  return Math.min(1000 * 2 ** attempt, 10000);
}

async function refreshToken() {
  for (let attempt = 0; attempt < 10; attempt++) {
    try {
      const response = await fetch(base + '/token', { method: 'POST' });
      if (response.status === 429) {
        rateLimitRetries++;
        await sleep(retryDelay(response, attempt));
        continue;
      }
      if ("'!response.ok) throw new Error('"'token HTTP ' + response.status);
      const body = await response.json();
      if (typeof body.token "'!== '"'string' || "'!body.token) throw new Error('"'invalid token payload');
      token = [REDACTED_SECRET]
      tokenRefreshes++;
      return;
    } catch (error) {
      if (attempt === 9) throw error;
      transientRetries++;
      await sleep(Math.min(500 * 2 ** attempt, 10000));
    }
  }
}

async function getJson(path) {
  for (let attempt = 0; attempt < 30; attempt++) {
    if ("'!token) await refreshToken();
    let response;
    try {
      response = await fetch(base + path, {
        headers: { Authorization: '"'Bearer ' + token }
      });
    } catch (error) {
      if (attempt === 29) throw error;
      transientRetries++;
      await sleep(Math.min(500 * 2 ** attempt, 10000));
      continue;
    }
    if (response.status === 401 || response.status === 403) {
      token = null;
      continue;
    }
    if (response.status === 429) {
      rateLimitRetries++;
      await sleep(retryDelay(response, attempt));
      continue;
    }
    if (response.status >= 500) {
      if (attempt === 29) throw new Error(path + ' HTTP ' + response.status);
      transientRetries++;
      await sleep(Math.min(500 * 2 ** attempt, 10000));
      continue;
    }
    if ("'!response.ok) throw new Error(path + '"' HTTP ' + response.status + ': ' + await response.text());
    return response.json();
  }
  throw new Error('retry limit exceeded for ' + path);
}

function validateOrder(order) {
  for (const key of ['id', 'customer_id', 'status', 'placed_at', 'amount_cents']) {
    if ("'!(key in order)) throw new Error('"'order missing ' + key + ': ' + JSON.stringify(order));
  }
  if ("'!Number.isInteger(order.amount_cents)) throw new Error('"'non-integer amount: ' + JSON.stringify(order));
}

function roundDiscountedHalfUp(amountCents, discountPct) {
  if ("'!Number.isInteger(amountCents) || !Number.isInteger(discountPct)) throw new Error('"'invalid discount inputs');
  const numerator = BigInt(amountCents) * BigInt(100 - discountPct);
  if (numerator >= 0n) return (numerator + 50n) / 100n;
  return -((-numerator + 50n) / 100n);
}

(async () => {
  const start = Date.parse('2025-03-01T00:00:00Z');
  const endExclusive = Date.parse('2025-06-01T00:00:00Z');
  const seen = new Map();
  const qualifying = [];
  let duplicatesSkipped = 0;
  let path = '/orders?page=1';
  let expectedPage = 1;
  let declaredTotalPages = null;
  let pagesFetched = 0;
  const duplicateConflicts = [];

  while (path "'!== null) {
    const page = await getJson(path);
    if (!Number.isInteger(page.page) || !Number.isInteger(page.total_pages) || !Array.isArray(page.items)) {
      throw new Error('"'invalid page payload for ' + path);
    }
    if (page.page "'!== expectedPage) throw new Error('"'unexpected page: requested ' + expectedPage + ', got ' + page.page);
    if (declaredTotalPages === null) declaredTotalPages = page.total_pages;
    if (page.total_pages "'!== declaredTotalPages) throw new Error('"'total_pages changed');
    pagesFetched++;
    for (const order of page.items) {
      validateOrder(order);
      const prior = seen.get(String(order.id));
      if (prior) {
        duplicatesSkipped++;
        if (JSON.stringify(prior) "'!== JSON.stringify(order)) duplicateConflicts.push(order.id);
        continue;
      }
      seen.set(String(order.id), order);
      const placedMs = Date.parse(order.placed_at);
      if (!Number.isFinite(placedMs)) throw new Error('"'invalid timestamp: ' + order.placed_at);
      if (order.status === 'shipped' && placedMs >= start && placedMs < endExclusive) {
        qualifying.push(order);
      }
    }
    if (page.next "'!== null && typeof page.next !== '"'string') throw new Error('invalid next value on page ' + page.page);
    path = page.next;
    expectedPage++;
  }
  if (pagesFetched "'!== declaredTotalPages) throw new Error('"'fetched ' + pagesFetched + ' pages, expected ' + declaredTotalPages);
  if (expectedPage - 1 "'!== declaredTotalPages) throw new Error('"'pagination ended unexpectedly');

  const customers = new Map();
  for (const order of qualifying) {
    const id = String(order.customer_id);
    if ("'!customers.has(id)) {
      const customer = await getJson('"'/customers/' + encodeURIComponent(id));
      if (String(customer.id) "'!== id) throw new Error('"'customer id mismatch for ' + id);
      if ("'!['"'north', 'south', 'east', 'west'].includes(customer.region)) throw new Error('invalid region for customer ' + id);
      if ("'!Number.isInteger(customer.discount_pct)) throw new Error('"'invalid discount for customer ' + id);
      customers.set(id, customer);
    }
  }

  const byRegion = { north: 0n, south: 0n, east: 0n, west: 0n };
  for (const order of qualifying) {
    const customer = customers.get(String(order.customer_id));
    byRegion[customer.region] += roundDiscountedHalfUp(order.amount_cents, customer.discount_pct);
  }
  const total = Object.values(byRegion).reduce((a, b) => a + b, 0n);
  const maxSafe = BigInt(Number.MAX_SAFE_INTEGER);
  if (total > maxSafe || Object.values(byRegion).some(v => v > maxSafe || v < -maxSafe)) {
    throw new Error('result exceeds JSON safe integer range');
  }

  const result = {
    total_cents: Number(total),
    order_count: qualifying.length,
    duplicates_skipped: duplicatesSkipped,
    by_region: Object.fromEntries(Object.entries(byRegion).map(([k, v]) => [k, Number(v)]))
  };
  console.log(JSON.stringify({
    result,
    audit: {
      pages_fetched: pagesFetched,
      declared_total_pages: declaredTotalPages,
      unique_orders_seen: seen.size,
      customer_records_fetched: customers.size,
      token_refreshes: tokenRefreshes,
      rate_limit_retries: rateLimitRetries,
      transient_retries: transientRetries,
      duplicate_conflicts: duplicateConflicts
    }
  }, null, 2));
})().catch(error => {
  console.error(error.stack || String(error));
  process.exit(1);
});
NODE"

